const items = $input.all();

// Extract JSON from markdown code blocks
const meetings = items.map(item => {
  let txt = item.json.output || "";

  txt = txt
    .replace(/```json/g, "")
    .replace(/```/g, "")
    .trim();

  return JSON.parse(txt);
});

// Collect all actions
const allActions = [];
meetings.forEach(meeting => {
  (meeting.actionItems || []).forEach(action => {
    allActions.push({
      meetingName: meeting.meetingName,
      meetingDate: meeting.meetingDate,
      sourceFile: meeting.sourceFile,
      owner: action.owner,
      task: action.task,
      dueDate: action.dueDate
    });
  });
});

let html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
body{
    font-family:Arial,Helvetica,sans-serif;
    color:#333;
    background:#f5f7fa;
    margin:0;
    padding:20px;
}
.container{
    max-width:1200px;
    margin:auto;
}
.header{
    background:#1f4e79;
    color:white;
    padding:20px;
    border-radius:8px;
}
.card{
    background:white;
    margin-top:20px;
    border-radius:8px;
    padding:20px;
    box-shadow:0 1px 4px rgba(0,0,0,0.15);
}
table{
    border-collapse:collapse;
    width:100%;
}
th{
    background:#1f4e79;
    color:white;
    padding:10px;
    text-align:left;
}
td{
    border:1px solid #ddd;
    padding:8px;
    vertical-align:top;
}
ul{
    margin:0;
    padding-left:20px;
}
.summary{
    background:#eef4fb;
    padding:12px;
    border-left:4px solid #1f4e79;
    margin-top:8px;
}
.badge{
    background:#e8f0fe;
    padding:4px 8px;
    border-radius:4px;
    font-size:12px;
}
</style>
</head>
<body>
<div class="container">

<div class="header">
<h1>📋 Meeting Action Digest</h1>
<p>Generated by n8n</p>
</div>

<div class="card">
<h2>🔥 Consolidated Action Tracker</h2>

<table>
<tr>
<th>Date</th>
<th>Meeting</th>
<th>Owner</th>
<th>Action</th>
<th>Due Date</th>
<th>Source File</th>
</tr>
`;

allActions.forEach(action => {
  html += `
  <tr>
    <td>${action.meetingDate || "-"}</td>
    <td>${action.meetingName || "-"}</td>
    <td>${action.owner || "-"}</td>
    <td>${action.task || "-"}</td>
    <td>${action.dueDate || "-"}</td>
    <td>${action.sourceFile || "-"}</td>
  </tr>
  `;
});

html += `
</table>
</div>
`;

meetings.forEach(meeting => {

  html += `
  <div class="card">

  <h2>${meeting.meetingName}</h2>

  <p>
    <span class="badge">📅 ${meeting.meetingDate || 'N/A'}</span>
    &nbsp;
    <span class="badge">📁 ${meeting.sourceFile || 'N/A'}</span>
  </p>

  <h3>Executive Summary</h3>
  <div class="summary">
  <ul>
  `;

  (meeting.executiveSummary || []).forEach(item => {
      html += `<li>${item}</li>`;
  });

  html += `
  </ul>
  </div>

  <h3>Action Items</h3>

  <table>
  <tr>
    <th>Owner</th>
    <th>Task</th>
    <th>Due Date</th>
  </tr>
  `;

  (meeting.actionItems || []).forEach(action => {
      html += `
      <tr>
        <td>${action.owner}</td>
        <td>${action.task}</td>
        <td>${action.dueDate}</td>
      </tr>
      `;
  });

  html += `
  </table>

  </div>
  `;
});

html += `
</div>
</body>
</html>
`;

return [{
  json: {
    html
  }
}];
